-- CocoFiber CMS: semua teks statis frontend yang bisa diedit dari Admin Dashboard
create or replace function set_updated_at() returns trigger as $$ begin new.updated_at = now(); return new; end; $$ language plpgsql;

create table if not exists site_content (
  id uuid primary key default gen_random_uuid(),
  key text unique not null,
  page text not null,
  label text not null,
  value_id text default '',
  value_en text default '',
  content_type text not null default 'text' check (content_type in ('text','html','attribute')),
  attribute_name text,
  status text not null default 'published' check (status in ('draft','published')),
  sort_order int default 0,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
alter table site_content enable row level security;
drop policy if exists "Publik bisa lihat konten published" on site_content;
create policy "Publik bisa lihat konten published" on site_content for select to anon using (status='published');
drop policy if exists "Admin bisa lihat semua konten" on site_content;
create policy "Admin bisa lihat semua konten" on site_content for select to authenticated using (true);
drop policy if exists "Admin bisa insert konten" on site_content;
create policy "Admin bisa insert konten" on site_content for insert to authenticated with check (true);
drop policy if exists "Admin bisa update konten" on site_content;
create policy "Admin bisa update konten" on site_content for update to authenticated using (true) with check (true);
drop policy if exists "Admin bisa delete konten" on site_content;
create policy "Admin bisa delete konten" on site_content for delete to authenticated using (true);
drop trigger if exists site_content_set_updated_at on site_content;
create trigger site_content_set_updated_at before update on site_content for each row execute function set_updated_at();

